// Classes de la Côte des Noyés (horreur, Cotentin, 1923) : dix classes, deux sous-classes chacune.
// Caractéristiques du genre : 0 Force, 1 Adresse, 2 Endurance, 3 Savoir, 4 Sang-froid, 5 Présence.
// Ni sort ni pouvoir surnaturel : des métiers, des relations, et un prix pour ce qui touche à la mer, aux morts et à ce qui va arriver.
// Ce prix est la Marée (jauge de 0 à 10) et les Présages : voir PRIX_COMMUN ci-dessous et la section « La Marée et les Présages » de noyes-regles.ts.
// Les niveaux élevés donnent des relations, des talents et des Présages mieux tenus, jamais des surhommes.
// Les textes sont lus par les joueurs : aucun secret du canon (shared/canon/horreur.ts) ici.
import type { ActionType, CharacterClass, Power, Recharge, Subclass } from "./rules";

const P = (level: number, name: string, action: ActionType, recharge: Recharge, effect: string, extra: Partial<Power> = {}): Power => ({ level, name, action, recharge, effect, ...extra });
const S = (id: string, name: string, pitch: string, description: string, powers: Power[]): Subclass => ({ id, name, pitch, description, powers });

/** Un pouvoir qui touche à la mer, aux morts ou à ce qui va arriver : il fait monter la Marée. */
const MAREE = (n: number) => ` Prix : Marée +${n}.`;
/** Un pouvoir qui fait passer ce qui va arriver : il dépense un Présage. */
const PRESAGE = " Prix : un Présage.";

/** Le passif commun aux classes qui touchent à la mer, aux morts ou à ce qui va arriver. */
const PRIX_COMMUN =
  "Un pouvoir marqué « Prix : Marée +N » fait monter ta Marée de N points (chaque point te donne un Présage, comme toujours). Un pouvoir marqué « Prix : un Présage » en dépense un, ce qui coûte 1 point de Marée sans te donner de Présage en retour. Les autres pouvoirs ne coûtent rien. Un seul pouvoir à prix par scène, et jamais s'il te porterait au-dessus de 9. On ne dépense pas de Présage à 9 de Marée. Le dixième point ne vient jamais d'un choix : seulement d'une lettre, d'un corps ou de la mer. Dépenser un Présage ordinaire (relancer un dé, poser une question) ne compte pas comme un pouvoir à prix. Ce que la mer annonce arrive : si les joueurs changent la scène, cela arrive sous une autre forme.";

/** DD des pouvoirs qui demandent une sauvegarde. */
const DD = " DD de la sauvegarde : 8 + ta maîtrise + ton modificateur de caractéristique principale.";

const PRIX_PHOTOGRAPHE =
  PRIX_COMMUN +
  " Quand une plaque te montre ce que la mer fait (la Fosse, une file sous l'eau, des lumières au large), la Marée monte comme si tu l'avais vu de tes yeux, mais tu as l'avantage à la sauvegarde. Tu peux aussi laisser la plaque dans sa boîte, ou la faire développer par un autre.";

